bits 64
global _start

%macro _loop 3
	_loop:
		movzx eax, byte [rbx]

		mov ecx, eax
		shr eax, 4
		and ecx, 0x0f

		mov al, [r8 + rax]
		mov cl, [r8 + rcx]
		mov [buf], al
		mov [buf+1], cl

		mov rsi, hexa
		mov rdx, 2
		mov rax, 1
		mov rdi, [fd_out]
		syscall

		mov rsi, buf
		mov rdx, 2
		mov rax, 1
		mov rdi, [fd_out]
		syscall

		inc rbx
		cmp byte [rbx], 0
		je _end

		mov rsi, comma
		mov rdx, 2
		mov rax, 1
		mov rdi, [fd_out]
		syscall

		jmp _loop
		_end:
%endmacro

%macro _prefix 2
	mov al, byte [i]
	dec al
	add al, '0'

	mov byte [source_data+2616], al

	mov rsi, source_data
	mov rdx, SOURCE_DATA_LEN-37
	mov rax, 1
	mov rdi, [fd_out]
	syscall
	mov byte [source_data+2616], 'X'
%endmacro

%macro _suffix 2
	mov rsi, source_data+SOURCE_DATA_LEN-37
	mov rdx, 37
	mov rax, 1
	mov rdi, [fd_out]
	syscall
%endmacro

section .bss
	fd_out: resq 1
    buf: resb 2

section .text
	_start:
		mov al, byte [i]
		cmp al, 0
		je _error

		dec al
		add al, '0'
		mov byte [exec+8], al
		mov byte [file_name+6], al
		mov byte [exec_name+6], al

		; create file
		mov rax, 257
		mov rdi, -100
		mov rsi, file_name
		mov rdx, 0x241
		mov r10, 0o777
		syscall

		mov [fd_out], rax

		_prefix source_data, SOURCE_DATA_LEN

		lea rbx, [source_data]
		lea r8, [hex_table]

		_loop hexa, comma, i

		_suffix source_data, SOURCE_DATA_LEN

		mov rdi, [fd_out]
		mov rax, 3
		syscall
	
		; compilation

		mov eax, 57 ; fork
		syscall
	
		cmp rax, 0
		je _child_cmp
		jmp _parent_cmp
		
		_child_cmp:
			mov rax, 59 ; syscall execve
			lea rdi, [rel comp]
			lea rsi, [rel args_comp]
			lea rdx, [rel envp]
			syscall
			jmp _error

		_parent_cmp:
			mov rdi, rax ; pid de l'enfant
			xor esi, esi
			xor edx, edx
			xor r10d, r10d
			mov eax, 61
			syscall

		; build
		mov eax, 57 ; fork
		syscall
	
		cmp rax, 0
		je _child_build
		jmp _parent_build
		
		_child_build:
			mov rax, 59 ; syscall execve
			lea rdi, [rel build]
			lea rsi, [rel args_build]
			lea rdx, [rel envp]
			syscall
			jmp _error

		_parent_build:
			mov rdi, rax ; pid de l'enfant
			xor esi, esi
			xor edx, edx
			xor r10d, r10d
			mov eax, 61
			syscall

		; execution

		mov eax, 57 ; fork
		syscall
	
		cmp rax, 0
		je _child_exec
		jmp _parent_exec
		
		_child_exec:
			mov rax, 59 ; syscall execve
			lea rdi, [rel exec]
			lea rsi, [rel args_exec]
			lea rdx, [rel envp]
			syscall
			jmp _error

		_parent_exec:
			mov rdi, rax ; pid de l'enfant
			xor esi, esi
			xor edx, edx
			xor r10d, r10d
			mov eax, 61
			syscall


		mov rax, 60
		mov rdi, 0
		syscall

		_error:
			mov rax, 60
			mov rdi, 1
			syscall


